head.script:
scwin.GRP_ID = "";
scwin.SEL_PJT_ID = "";

/**
 * @method
 * @name scwin.onpageload
 * @description 페이지 로드 시 초기화 작업을 수행한다.
 * @example
 * scwin.onpageload();
 */
scwin.onpageload = function () {
    // 페이지 로드 시 사이드바를 숨김 상태로 시작
    scwin.hideSidebar();

    // 초기화 완료 후 실행
    setTimeout(function () {
        try {
            // 기존 탭 모두 삭제
            tab_content.deleteAllTabs();

            // HOME 탭 추가
            tab_content.addTab("dashboardTab", {
                label: "HOME",
                closable: false,
                openAction: "select"
            }, {
                src: "dashboard.xml",
                frameMode: "wframe"
            });
        } catch (e) {
            // 초기 탭 생성 실패 시 재시도
            scwin.initializeDefaultTab();
        }
    }, 200);
};

/**
 * @method
 * @name scwin.initializeDefaultTab
 * @description 기본 탭 초기화 함수 (재시도 로직)
 * @example
 * scwin.initializeDefaultTab();
 */
scwin.initializeDefaultTab = function () {
    var retryCount = 0;
    var maxRetries = 5;

    var tryInitTab = function () {
        try {
            if (tab_content && typeof tab_content.addTab === 'function') {
                // 기존 탭 모두 삭제
                tab_content.deleteAllTabs();

                // HOME 탭 생성
                tab_content.addTab("dashboardTab", {
                    label: "HOME",
                    closable: false,
                    openAction: "select"
                }, {
                    src: "dashboard.xml",
                    frameMode: "wframe"
                });
            } else {
                throw new Error("tab_content가 초기화되지 않음");
            }
        } catch (e) {
            retryCount++;
            if (retryCount < maxRetries) {
                // 점진적 지연으로 재시도
                setTimeout(tryInitTab, 200 * retryCount);
            }
        }
    };

    tryInitTab();
};


/**
 * @method
 * @name scwin.showSidebar
 * @description 사이드바를 보여준다.
 * @example
 * scwin.showSidebar();
 */
scwin.showSidebar = function () {
    grp_menu.removeClass("closed");
};

/**
 * @method
 * @name scwin.hideSidebar
 * @description 사이드바를 숨긴다.
 * @example
 * scwin.hideSidebar();
 */
scwin.hideSidebar = function () {
    grp_menu.addClass("closed");
};

/**
 * @method
 * @name scwin.toggleSidebar
 * @description 사이드바를 토글한다.
 * @example
 * scwin.toggleSidebar();
 */
scwin.toggleSidebar = function () {
    if (grp_menu.hasClass("closed")) {
        scwin.showSidebar();
    } else {
        scwin.hideSidebar();
    }
};

/**
 * @method
 * @name scwin.onProjectChange
 * @description 프로젝트 변경 시 사이드바와 메뉴를 업데이트한다.
 * @param {string} pjtId - 프로젝트 ID
 * @param {Array} grpId - 그룹 ID 배열
 * @example
 * scwin.onProjectChange('1', ['1']);
 */
scwin.onProjectChange = function (pjtId, grpId) {
    // 프로젝트 ID 유무에 따라 사이드바 제어
    if (pjtId && pjtId !== "") {
        scwin.showSidebar();
    } else {
        scwin.hideSidebar();
    }

    // 메뉴 목록을 가져오는 서브미션 실행
    scwin.SEL_PJT_ID = pjtId;
    scwin.GRP_ID = grpId ? grpId[0] : "";

    $c.sbm.execute(sbm_selectMenuList, {
        "elData": { "grpId": scwin.GRP_ID }
    });
};

/**
 * @method
 * @name scwin.createMenuWithGenerator
 * @description 웹스퀘어 Generator를 사용하여 동적 메뉴를 생성한다.
 * @example
 * scwin.createMenuWithGenerator();
 */
scwin.createMenuWithGenerator = function () {
    var genObj = gen_menu;
    genObj.removeAll();

    var menuListLength = dlt_menuVoList.getRowCount();
    var menuGroups = {};

    // 1뎁스와 2뎁스 메뉴를 분리하여 그룹화
    for (var i = 0; i < menuListLength; i++) {
        var menuData = dlt_menuVoList.getRowJSON(i);
        var parentId = menuData.parentMenuId || 'root';

        if (parentId === 'root' || parentId === '') {
            // 1뎁스 메뉴인 경우
            if (!menuGroups[menuData.menuId]) {
                menuGroups[menuData.menuId] = {
                    menu: menuData,
                    children: []
                };
            }
        } else {
            // 2뎁스 메뉴인 경우
            if (!menuGroups[parentId]) {
                menuGroups[parentId] = {
                    menu: null,
                    children: []
                };
            }
            menuGroups[parentId].children.push(menuData);
        }
    }

    // 그룹화된 메뉴 데이터로 실제 메뉴 DOM 생성
    for (var groupId in menuGroups) {
        var group = menuGroups[groupId];
        if (group.menu) {
            // 1뎁스 메뉴 생성
            var idx = genObj.insertChild();
            var menuObj = genObj.getChild(idx, "anc_menu");

            // 1뎁스 메뉴 설정
            menuObj.setValue(group.menu.menuName);
            menuObj.setUserData("menuId", group.menu.menuId);
            menuObj.setUserData("menuUrl", group.menu.menuUrl);
            menuObj.setUserData("hasChildren", group.children.length > 0 ? "Y" : "N");

            // 메뉴 클릭 이벤트 추가
            scwin.addMenuClickEvent(menuObj, idx);

            // 2뎁스 메뉴가 있는 경우 하위 메뉴 생성
            if (group.children.length > 0) {
                var subGenObj = genObj.getChild(idx, "gen_subMenu");
                for (var j = 0; j < group.children.length; j++) {
                    var childMenu = group.children[j];
                    var subIdx = subGenObj.insertChild();
                    var subMenuObj = subGenObj.getChild(subIdx, "anc_subMenu");

                    // 2뎁스 메뉴 설정
                    subMenuObj.setValue(childMenu.menuName);
                    subMenuObj.setUserData("menuId", childMenu.menuId);
                    subMenuObj.setUserData("menuUrl", childMenu.menuUrl);
                    subMenuObj.setUserData("parentId", childMenu.parentId);

                    // 서브메뉴 클릭 이벤트 추가
                    scwin.addSubmenuClickEvent(subMenuObj, idx, subIdx);
                }
            }
        }
    }
};

/**
 * @method
 * @name scwin.addMenuClickEvent
 * @description 메뉴 전체 영역에 클릭 이벤트를 추가한다.
 * @param {Object} menuObj - 메뉴 객체
 * @param {number} idx - 메뉴 인덱스
 * @example
 * scwin.addMenuClickEvent(menuObj, 0);
 */
scwin.addMenuClickEvent = function (menuObj, idx) {
    setTimeout(function () {
        var menuElement = document.getElementById(menuObj.getID());
        if (menuElement && menuElement.parentElement) {
            var parentEl = menuElement.parentElement;

            // 클릭 이벤트 추가
            parentEl.addEventListener('click', function (e) {
                e.preventDefault();
                e.stopPropagation();
                scwin.menu_onclick.call(menuObj);
            });

            // 커서 스타일 설정
            if (!parentEl.style.cursor) {
                parentEl.style.cursor = 'pointer';
            }
        }
    }, 100);
};

/**
 * @method
 * @name scwin.addSubmenuClickEvent
 * @description 서브메뉴 전체 영역에 클릭 이벤트를 추가한다.
 * @param {Object} subMenuObj - 서브메뉴 객체
 * @param {number} parentIdx - 상위 메뉴 인덱스
 * @param {number} subIdx - 서브메뉴 인덱스
 * @example
 * scwin.addSubmenuClickEvent(subMenuObj, 0, 0);
 */
scwin.addSubmenuClickEvent = function (subMenuObj, parentIdx, subIdx) {
    setTimeout(function () {
        var submenuElement = document.getElementById(subMenuObj.getID());
        if (submenuElement && submenuElement.parentElement) {
            var parentEl = submenuElement.parentElement;

            // 클릭 이벤트 추가
            parentEl.addEventListener('click', function (e) {
                e.preventDefault();
                e.stopPropagation();
                scwin.submenu_onclick.call(subMenuObj);
            });

            // 커서 스타일 설정
            if (!parentEl.style.cursor) {
                parentEl.style.cursor = 'pointer';
            }
        }
    }, 100);
};

/**
 * @method
 * @name scwin.menu_onclick
 * @description 1뎁스 메뉴 클릭 이벤트를 처리한다.
 * @example
 * scwin.menu_onclick();
 */
scwin.menu_onclick = function () {
    var hasChildren = this.getUserData("hasChildren");
    var menuUrl = this.getUserData("menuUrl");

    if (hasChildren === "Y") {
        // 하위 메뉴 토글
        scwin.toggleSubMenu(this);
    } else if (menuUrl && menuUrl.trim() !== "") {
        // 단일 페이지 메뉴인 경우 탭으로 열기
        var menuName = this.getValue();
        scwin.openTab(menuUrl, menuName);
    }
};

/**
 * @method
 * @name scwin.submenu_onclick
 * @description 2뎁스 메뉴 클릭 이벤트를 처리한다.
 * @example
 * scwin.submenu_onclick();
 */
scwin.submenu_onclick = function () {
    var menuUrl = this.getUserData("menuUrl");
    var menuName = this.getValue();

    if (menuUrl && menuUrl.trim() !== "") {
        scwin.openTab(menuUrl, menuName);
    }
};

/**
 * @method
 * @name scwin.toggleSubMenu
 * @description 하위 메뉴를 토글한다 (아코디언 효과 적용).
 * @param {Object} menuObj - 메뉴 객체
 * @example
 * scwin.toggleSubMenu(menuObj);
 */
scwin.toggleSubMenu = function (menuObj) {
    var gen = menuObj.getGenerator();
    var idx = menuObj.getGeneratedIndex();
    var subNavObj = gen.getChild(idx, 'gen_subMenu');

    // 다른 모든 하위 메뉴 닫기 (아코디언 효과)
    for (var i = 0; i < gen.getLength(); i++) {
        if (i !== idx) {
            var otherSubNav = gen.getChild(i, 'gen_subMenu');
            otherSubNav.hide();
            otherSubNav.removeClass('submenu-show');
        }
    }

    // 현재 메뉴의 하위 메뉴 토글
    if (subNavObj.getStyle('display') === 'none' || !subNavObj.getStyle('display')) {
        subNavObj.show();
        subNavObj.addClass('submenu-show');
    } else {
        subNavObj.hide();
        subNavObj.removeClass('submenu-show');
    }
};

/**
 * @method
 * @name scwin.openTab
 * @description 커스텀 탭 열기 함수
 * @param {string} url - 열 페이지 URL
 * @param {string} title - 탭 제목
 * @param {Object} tabData - 전달할 탭 데이터 (선택)
 * @example
 * scwin.openTab('dashboard.xml', 'HOME');
 */
scwin.openTab = async function (url, title, tabData) {
    var tabId = "tab_" + new Date().getTime();

    try {
        var tabInfo = tab_content.getTabInfo();
        var existingTabId = null;
        var existingTabIndex = -1;

        // 같은 URL의 탭이 이미 열려있는지 확인
        for (var i = 0; i < tabInfo.length; i++) {
            if (tabInfo[i] && tabInfo[i].src === url) {
                existingTabId = tabInfo[i].id;  // 기존 탭 ID 저장
                existingTabIndex = i;
                break;
            }
        }

        // contentOptions 설정
        var contentOptions = {
            "src": url,
            "frameMode": "wframePreload",
            "scope": true,
            "alwaysDraw": true
        };

        if (tabData) {
            contentOptions.dataObject = {
                "type": "json",
                "name": "tabData",
                "data": tabData
            };
        }

        if (existingTabIndex !== -1) {
            // 기존 탭ID로 exist 옵션 사용
            // 기존 탭 갱신

            var newTabId = await tab_content.addTab(existingTabId, {
                "label": title,
                "closable": true,
                "openAction": "exist"  // 기존 탭 내용을 새로 고침
            }, contentOptions);

            await tab_content.setSelectedTabIndex(existingTabIndex);
        } else {
            // 새 탭인 경우 (기존 로직 유지)
            var newTabId = await tab_content.addTab(tabId, {
                "label": title,
                "closable": true,
                "openAction": "new"
            }, contentOptions);

            await tab_content.setSelectedTabIndex(newTabId);
        }

    } catch (e) {
        // 탭 생성 실패
        scwin.showGlobalToast("페이지를 로드할 수 없습니다: " + title, "error");
    }
};

/**
 * @method
 * @name scwin.btn_closeAllTabs_onclick
 * @description 모든 탭 닫기 버튼 클릭 이벤트를 처리한다.
 * @param {Event} e - 클릭 이벤트 객체
 * @example
 * scwin.btn_closeAllTabs_onclick();
 */
scwin.btn_closeAllTabs_onclick = function () {
    try {
        // 현재 열린 탭 개수 확인
        var tabCount = tab_content.getTabCount();

        if (tabCount <= 1) {
            scwin.showGlobalToast("닫을 탭이 없습니다", "warning");
            return;
        }

        // 사용자 확인
        var promise = $c.win.confirm("모든 탭을 닫으시겠습니까?\n(HOME 탭은 유지됩니다)")
        promise.then(function (result) {
            if (result) {
                // 모든 탭 삭제
                tab_content.deleteAllTabs();

                // HOME 탭 재생성
                setTimeout(function () {
                    tab_content.addTab("dashboardTab", {
                        label: "HOME",
                        closable: false,
                        openAction: "select"
                    }, {
                        src: "dashboard.xml",
                        frameMode: "wframe"
                    });
                }, 100);
            }
        });

    } catch (e) {
        scwin.showGlobalToast("탭을 닫는 중 오류가 발생했습니다", "error");
    }
};

/**
 * @method
 * @name scwin.sbm_selectMenuList_submitdone
 * @description 메뉴 목록 조회 서브미션 완료 후 처리한다.
 * @param {Object} e - 서브미션 이벤트 객체
 * @example
 * scwin.sbm_selectMenuList_submitdone(e);
 */
scwin.sbm_selectMenuList_submitdone = function (e) {
    var elData = e.responseJSON.elData;
    var elHeader = e.responseJSON.elHeader;

    if (elHeader == null || elHeader === "" || elHeader === "undefined" || elHeader.resSuc === false) {
        scwin.showGlobalToast(`에러코드: ${elHeader.resCode} - ${elHeader.resMsg}`, "error");
        return false;
    }

    // 메뉴 데이터 설정 및 동적 메뉴 생성
    dlt_menuVoList.setJSON(elData.menuVo);
    scwin.createMenuWithGenerator();

    // HOME 탭 초기화
    tab_content.deleteAllTabs();
    tab_content.addTab("dashboardTab", {
        label: "HOME",
        closable: false,
        openAction: "select"
    }, {
        src: "dashboard.xml",
        frameMode: "wframe"
    });
};

/**
 * @method
 * @name scwin.showGlobalToast
 * @description 전역 토스트 알림창을 표시한다.
 * @param {string} message - 표시할 메시지
 * @param {string} type - 토스트 타입 (success, error, warning, info)
 * @param {number} duration - 표시 시간 (기본 3초)
 * @example
 * scwin.showGlobalToast('성공', 'success', 3000);
 */
scwin.showGlobalToast = function(message, type = 'success', duration = 3000) {
    var toastElement = $p.$("#txt_globalToast")[0];

    // 메시지 설정
    txt_globalToast.setValue(message);

    // 기존 클래스 제거 후 새 클래스 적용
    toastElement.className = `notification-toast ${type}`;

    // 토스트 표시
    toastElement.style.display = 'block';

    // 슬라이드 인 애니메이션
    setTimeout(function() {
        toastElement.classList.add('show');
    }, 50);

    // 자동 숨김
    setTimeout(function() {
        scwin.hideGlobalToast();
    }, duration);
};

/**
 * @method
 * @name scwin.hideGlobalToast
 * @description 전역 토스트 알림창을 숨긴다.
 * @example
 * scwin.hideGlobalToast();
 */
scwin.hideGlobalToast = function() {
    var toastElement = $p.$("#txt_globalToast")[0];

    // 페이드 아웃 효과 적용
    toastElement.classList.add('fade-out');
    toastElement.classList.remove('show');

    // 애니메이션 완료 후 숨김
    setTimeout(function() {
        toastElement.style.display = 'none';
        toastElement.classList.remove('fade-out');
    }, 300);
};
